mapper.select:
SELECT COUNT(*)
  FROM cart
 WHERE mno = #{mno}

SELECT c.cno, c.ctype, c.cstock, c.mno, c.bno, b.bname, b.bprice, b.bimg, c.pno, p.pname, p.pprice, p.pimg, p.ptype FROM cart c LEFT JOIN book b ON c.bno = b.bno LEFT JOIN pass p ON c.pno = p.pno WHERE c.cno IN
#{cno}
ORDER BY c.cno DESC

SELECT *
  FROM CART
 WHERE MNO=#{mno}
   AND BNO=#{bno}

mapper.delete:
DELETE FROM CART
 WHERE MNO=#{mno}
   AND BNO=#{bno}
